let user=null,data=null,current=null,targets=[],dirty=false;const $=id=>document.getElementById(id);const esc=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;');function half(h){return h==='first'?'상반기':'하반기'}function status(s){return s==='active'?'진행중':s==='closed'?'종료':'준비중'}function statusClass(s){return s==='active'?'active':s==='closed'?'closed':'draft'}
const api=(path,opt={})=>window.EHSApi.request(path,opt);
function renderList(){const list=data?.cycles||[];$('cycleList').innerHTML=list.length?list.map(c=>`<button class="cycle-btn ${current?.id===c.id?'active':''}" data-id="${esc(c.id)}"><div class="cycle-title">${c.year}년 ${half(c.half)}</div><div class="cycle-meta">${esc(c.template_name||'')} · <span class="tag ${statusClass(c.status)}">${status(c.status)}</span></div></button>`).join(''):'<div class="empty">연결된 평가회차가 없습니다.</div>';$('cycleList').querySelectorAll('.cycle-btn').forEach(b=>b.onclick=()=>loadBundle(b.dataset.id))}
function selectedCount(){return targets.filter(x=>Number(x.is_selected)===1).length}function exemptCount(){return targets.filter(x=>x.exemption_type==='ipass_excellent').length}function stateCount(...s){return targets.filter(x=>Number(x.is_selected)===1&&s.includes(x.status)).length}
function render(){renderList();if(!current){$('workspace').innerHTML='<div class="empty">평가회차를 선택하거나 평가표를 연결하세요.</div>';return}const editable=current.status==='draft';$('workspace').innerHTML=`<div class="card-head"><strong>${esc(current.cycle_name)}</strong><span class="tag ${statusClass(current.status)}">${status(current.status)}</span></div><div class="editor"><div class="form"><div class="field"><label>평가 시작일</label><input id="startAt" type="date" value="${esc(current.start_at||'')}" ${editable?'':'disabled'}></div><div class="field"><label>평가 종료일</label><input id="endAt" type="date" value="${esc(current.end_at||'')}" ${editable?'':'disabled'}></div><div class="field name"><label>회차명</label><input id="cycleName" value="${esc(current.cycle_name||'')}" ${editable?'':'disabled'}></div></div><div class="status-strip"><div class="metric"><span>평가대상</span><b>${selectedCount()}개사</b></div><div class="metric"><span>상반기 면제</span><b>${exemptCount()}개사</b></div><div class="metric"><span>제출완료</span><b>${stateCount('submitted','evaluating','completed','published')}개사</b></div><div class="metric"><span>평가완료</span><b>${stateCount('completed','published')}개사</b></div></div>${current.half==='first'?`<div class="notice exempt">전년도 i-PaSS ${Number(data.policy?.excellence_threshold??90)}점 이상 협력사는 상반기 평가대상에서 자동 제외됩니다. 면제사는 해당 연도 하반기 평가가 ${Number(data.policy?.exempt_second_half_weight??80)}%로 반영됩니다.</div>`:''}<div class="tools"><strong>대상 협력사</strong><div class="tools-right">${editable?'<button class="btn" id="selectAll">면제 제외 전체 선택</button><button class="btn" id="clearAll">전체 해제</button>':''}<input id="search" class="search" placeholder="협력사 검색"></div></div><div class="table-wrap"><table class="targets"><thead><tr><th style="width:52px">대상</th><th>협력사</th><th>업종</th><th style="width:110px">상시근로자</th><th>제외/면제 사유</th><th style="width:90px">전년 점수</th></tr></thead><tbody id="targetBody"></tbody></table></div><div class="foot"><span id="saved" class="saved"></span>${editable?'<button class="btn" id="saveBtn">저장</button><button class="btn primary" id="startBtn">평가 시작</button>':current.status==='active'?'<button class="btn danger" id="closeBtn">평가 종료</button>':'<button class="btn" disabled>종료된 평가</button>'}</div></div>`;renderTargets();bind()}
function renderTargets(q=''){const editable=current.status==='draft',s=String(q||'').trim().toLowerCase();const list=targets.filter(x=>!s||`${x.company_name} ${x.industry_name||''}`.toLowerCase().includes(s));$('targetBody').innerHTML=list.map(x=>{const exempt=x.exemption_type==='ipass_excellent';return `<tr class="${exempt?'exempt-row':''}" data-id="${esc(x.company_id)}"><td><input class="sel" type="checkbox" ${Number(x.is_selected)===1?'checked':''} ${!editable||exempt?'disabled':''}></td><td><b>${esc(x.company_name)}</b></td><td>${esc(x.industry_name||'-')}</td><td><input class="workers" type="number" min="0" value="${x.worker_count??''}" ${editable&&!exempt?'':'disabled'}></td><td class="reason">${exempt?`<span class="tag active">상반기 면제</span> ${esc(x.exclusion_reason||'')}`:Number(x.is_selected)===1?'-':esc(x.exclusion_reason||'평가대상 제외')}</td><td>${x.previous_ipass_score==null?'-':`<span class="score">${Number(x.previous_ipass_score)}점</span>`}</td></tr>`}).join('')||'<tr><td colspan="6" class="empty">검색 결과가 없습니다.</td></tr>';if(editable){$('targetBody').querySelectorAll('tr[data-id]').forEach(tr=>{const t=targets.find(x=>x.company_id===tr.dataset.id),c=tr.querySelector('.sel'),w=tr.querySelector('.workers');if(c)c.onchange=()=>{t.is_selected=c.checked?1:0;t.exclusion_reason=c.checked?null:'관리자 평가대상 제외';dirty=true;render()};if(w)w.onchange=()=>{t.worker_count=w.value===''?null:Math.max(0,Math.round(Number(w.value)||0));dirty=true}})}}
function bind(){if($('search'))$('search').oninput=e=>renderTargets(e.target.value);if($('selectAll'))$('selectAll').onclick=()=>{targets.forEach(x=>{if(x.exemption_type!=='ipass_excellent'){x.is_selected=1;x.exclusion_reason=null}});dirty=true;render()};if($('clearAll'))$('clearAll').onclick=()=>{targets.forEach(x=>{if(x.exemption_type!=='ipass_excellent'){x.is_selected=0;x.exclusion_reason='관리자 평가대상 제외'}});dirty=true;render()};if($('saveBtn'))$('saveBtn').onclick=saveCycle;if($('startBtn'))$('startBtn').onclick=startCycle;if($('closeBtn'))$('closeBtn').onclick=closeCycle;if(current.status==='draft'){const foot=document.querySelector('.foot'),b=document.createElement('button');b.className='btn';b.type='button';b.textContent='회차 설정';b.onclick=openCycleSettings;foot.insertBefore(b,$('saveBtn'))}['startAt','endAt','cycleName'].forEach(id=>{if($(id))$(id).oninput=()=>dirty=true})}
async function saveCycle(){try{const body={start_at:$('startAt').value,end_at:$('endAt').value,cycle_name:$('cycleName').value.trim(),targets:targets.map(x=>({company_id:x.company_id,is_selected:Number(x.is_selected)===1,exclusion_reason:x.exclusion_reason,worker_count:x.worker_count}))};await api(`/api/admin/evaluation-runtime/cycles/${encodeURIComponent(current.id)}`,{method:'PATCH',body:JSON.stringify(body)});dirty=false;$('saved').textContent='✓ 저장됨';await loadBundle(current.id)}catch(e){alert(e.message)}}async function startCycle(){if(dirty)await saveCycle();if(!confirm('평가를 시작할까요? 현재 평가표 내용은 이 회차에 복사되어 보존되고, 원본 평가표는 계속 수정할 수 있습니다.'))return;try{await api(`/api/admin/evaluation-runtime/cycles/${encodeURIComponent(current.id)}/start`,{method:'POST',body:'{}'});dirty=false;await loadBundle(current.id)}catch(e){alert(e.message)}}async function closeCycle(){if(!confirm('이 평가회차를 종료할까요? 원본 평가표에는 영향을 주지 않습니다.'))return;try{await api(`/api/admin/evaluation-runtime/cycles/${encodeURIComponent(current.id)}/close`,{method:'POST',body:'{}'});await loadBundle(current.id)}catch(e){alert(e.message)}}
function showModal(title,body,actions){$('modalTitle').textContent=title;$('modalBody').innerHTML=body;$('modalActions').innerHTML=actions;$('modal').classList.remove('hidden')}function closeModal(){$('modal').classList.add('hidden')}function pick(id){return $(id)?.querySelector('.selected')?.dataset.value}function bindChoices(id,onchange){$(id)?.querySelectorAll('.choice').forEach(b=>b.onclick=()=>{b.parentElement.querySelectorAll('.choice').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');onchange?.()})}
function openCreate(){const templates=data.templates||[];if(!templates.length)return alert('먼저 평가표를 만들어 주세요.');const now=new Date().getFullYear();showModal('새 평가회차',`<div class="setting-section"><h4>평가 연도</h4><div class="choice-grid" id="createYears">${[now,now+1].map((y,i)=>`<button class="choice ${i===0?'selected':''}" data-value="${y}" type="button">${y}년</button>`).join('')}</div></div><div class="setting-section"><h4>평가 시기</h4><div class="choice-grid" id="createHalves"><button class="choice selected" data-value="first" type="button">상반기<small>1월~6월 평가</small></button><button class="choice" data-value="second" type="button">하반기<small>7월~12월 평가</small></button></div></div><div class="setting-section"><h4>사용할 평가표</h4><div class="choice-grid" id="createTemplates">${templates.map((t,i)=>`<button class="choice ${i===0?'selected':''}" data-value="${esc(t.id)}" type="button">${t.year}년 ${half(t.half)}<small>${esc(t.name)} · ${Number(t.score_total||0)}점</small></button>`).join('')}</div></div><div class="setting-section"><div class="field"><label>회차명</label><input id="createName" placeholder="비워두면 자동으로 입력됩니다."></div></div><p>같은 연도·반기에 운영 중인 회차가 있으면 중복 생성하지 않습니다. 선택한 평가표의 설정은 회차별 설정으로 복사됩니다.</p>`,`<button class="btn" id="modalCancel">취소</button><button class="btn primary" id="modalCreate">회차 만들기</button>`);bindChoices('createYears');bindChoices('createHalves');bindChoices('createTemplates');$('modalCancel').onclick=closeModal;$('modalCreate').onclick=async()=>{const year=Number(pick('createYears')),halfValue=pick('createHalves');if((data.cycles||[]).some(c=>Number(c.year)===year&&c.half===halfValue))return alert(`${year}년 ${half(halfValue)} 회차가 이미 있습니다.`);const b=$('modalCreate');b.disabled=true;b.textContent='만드는 중...';try{const d=await api('/api/admin/evaluation-runtime/cycles',{method:'POST',body:JSON.stringify({template_id:pick('createTemplates'),year,half:halfValue,cycle_name:$('createName').value.trim()||null})});closeModal();await loadBundle(d.cycle.id)}catch(e){b.disabled=false;b.textContent='회차 만들기';alert(e.message)}}}
function settingValue(id){return Number($(id).value)}function openCycleSettings(){const s=data.settings||{};showModal('회차 설정',`<div class="setting-section"><h4>평가 컨셉</h4><textarea id="cycleConcept" placeholder="이번 회차의 중점 평가 내용을 입력하세요.">${esc(s.concept_text||'')}</textarea></div><div class="setting-section"><h4>협력사 등급</h4><div class="setting-grid"><div class="field"><label>안전관리 우수협력사</label><input id="cycleExcellent" type="number" value="${Number(s.excellent_min??90)}"></div><div class="field"><label>적격 협력사</label><input id="cycleQualified" type="number" value="${Number(s.qualified_min??70)}"></div></div><div class="grade-strip"><span>${Number(s.excellent_min??90)}점 이상 우수</span><span>${Number(s.qualified_min??70)}점 이상 적격</span><span>${Number(s.qualified_min??70)}점 미만 역량 강화</span></div></div><div class="setting-section"><h4>면제 및 점수 반영</h4><div class="setting-grid"><div class="field"><label>면제 기준</label><input id="cycleExemption" type="number" value="${Number(s.exemption_threshold??90)}"></div><div class="field"><label>면제 시 하반기</label><input id="cycleExemptSecond" type="number" value="${Number(s.exempt_second_half_weight??80)}"></div><div class="field"><label>일반 상반기</label><input id="cycleFirst" type="number" value="${Number(s.normal_first_half_weight??40)}"></div><div class="field"><label>일반 하반기</label><input id="cycleSecond" type="number" value="${Number(s.normal_second_half_weight??40)}"></div><div class="field"><label>협의체</label><input id="cycleCommittee" type="number" value="${Number(s.committee_weight??10)}"></div><div class="field"><label>산업재해</label><input id="cycleAccident" type="number" value="${Number(s.industrial_accident_weight??10)}"></div></div></div>`,`<button class="btn" id="modalCancel">취소</button><button class="btn primary" id="modalSaveSettings">설정 저장</button>`);$('modalCancel').onclick=closeModal;$('modalSaveSettings').onclick=async()=>{const settings={concept_text:$('cycleConcept').value.trim(),excellent_min:settingValue('cycleExcellent'),qualified_min:settingValue('cycleQualified'),exemption_threshold:settingValue('cycleExemption'),normal_first_half_weight:settingValue('cycleFirst'),normal_second_half_weight:settingValue('cycleSecond'),exempt_second_half_weight:settingValue('cycleExemptSecond'),committee_weight:settingValue('cycleCommittee'),industrial_accident_weight:settingValue('cycleAccident')};try{await api(`/api/admin/evaluation-runtime/cycles/${encodeURIComponent(current.id)}`,{method:'PATCH',body:JSON.stringify({settings})});closeModal();await loadBundle(current.id)}catch(e){alert(e.message)}}}
$('createBtn').onclick=openCreate;
async function loadBundle(id=''){if(dirty&&!confirm('저장하지 않은 변경사항이 있습니다. 이동할까요?'))return;dirty=false;$('workspace').innerHTML='<div class="loading">불러오는 중...</div>';try{data=await api(`/api/admin/evaluation-runtime${id?`?cycle_id=${encodeURIComponent(id)}`:''}`);if(data.settings)data.policy={...data.settings,excellence_threshold:data.settings.exemption_threshold};current=data.cycle||null;targets=data.companies||[];render()}catch(e){$('workspace').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}$('homeBtn').onclick=()=>{if(!dirty||confirm('저장하지 않은 변경사항이 있습니다. 이동할까요?'))location.href='/home'};$('refreshBtn').onclick=()=>loadBundle(current?.id||'');window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
(async()=>{try{user=await window.EHSAuth.requireUser({role:'admin'});$('userLabel').textContent=user.name||user.email||'';await loadBundle()}catch(e){if(e?.status===401)return;$('workspace').innerHTML=`<div class="empty">${esc(window.EHSApi.describe(e))}</div>`}})();
